syntax:
enum Color { Red = 0, Green = 1, Blue = 2 };  // Unscoped enumeration; underlying type is int by default
// Implicit conversion to int is allowed: int value = Green;  // Compiles successfully

enum class SColor : unsigned int { Red = 0, Green = 1, Blue = 2 };  // Scoped enumeration; explicit underlying type
// No implicit conversion: int value2 = SColor::Green;  // Compile-time error; requires static_cast<int>(SColor::Green)

// Implementation notes: For unscoped enums, the compiler maps enumerators to integer constants at compile-time. For scoped enums, the compiler treats them as distinct types, enforcing namespace qualification and blocking implicit promotions to prevent type mismatches.
